using System.Text;
using FinanceTracker.Generated.Shared;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace FinanceTracker.Generated.Attributes;

/// <summary>
/// Adds the <c>Transient</c> attribute, which registers a class as a transient service.
/// </summary>
[Generator]
public class TransientAttributeGenerator : IIncrementalGenerator
{
    /// <summary>
    /// The attribute's source.
    /// </summary>
    private const string AttributeSourceCode = $$"""
                                                 // <auto-generated/>
                                                 namespace {{SourceGeneratorConstants.GeneratedNamespace}}
                                                 {
                                                     /// <summary>
                                                     /// Registers the class as a transient service, by the method its
                                                     /// <c>[InjectionCategory]</c> says.
                                                     /// </summary>
                                                     /// <typeparam name="TServiceInterface">
                                                     /// What it's registered as.
                                                     /// </typeparam>
                                                     [System.AttributeUsage(System.AttributeTargets.Class, AllowMultiple = true)]
                                                     internal class {{SourceGeneratorConstants.TransientAttributeName}}<TServiceInterface> : System.Attribute
                                                     {
                                                     }
                                                 }
                                                 """;

    /// <inheritdoc/>
    public void Initialize(IncrementalGeneratorInitializationContext context) =>
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource(
            $"{SourceGeneratorConstants.TransientAttributeName}.g.cs",
            SourceText.From(AttributeSourceCode, Encoding.UTF8)));
}
